        long value = values[0];
        if (value == Long.MIN_VALUE) {
          writeRawNoEnsure(MIN_LONG_BYTES);
        } else {
          if (value < 0) {
            buffer[position++] = (byte) '-';
            value = -value;
          }
          if (value <= Integer.MAX_VALUE) {
            writePositiveIntNoEnsure((int) value);
          } else {
            position = writePositiveLong(buffer, position, value);
